def run(context):
    # Identify symbols for adding or trimming based on scores
    results = {'add_candidates': [], 'trim_candidates': []}
    for holding in context['portfolio.holdings'].values():
        symbol = holding['symbol']
        stage_snapshot = context['scores.stage_snapshots'].get(symbol)
        if stage_snapshot:
            technical_score = stage_snapshot.get('technical_score', 0)
            if technical_score > 70:  # Threshold for adding
                results['add_candidates'].append(symbol)
            elif technical_score < 30:  # Threshold for trimming
                results['trim_candidates'].append(symbol)
    return results

